  "nodes": {
    "Component": [
      {
        "component_id": "comp_control_board",
        "name": "Control board",
        "description": "Board installed in the front panel and connected to the power board by a ribbon cable.",
        "category": "control"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board within the power supply; it connects to the control board and includes a TORCH START connector.",
        "category": "electrical"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Board in the power supply connected at J1, J2, and J3, with MOSFET and diode mounted to the heatsink using thermal strips.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "Assembly containing the boards and heatsink addressed in the component replacement procedures.",
        "category": "electrical"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "Panel that holds the control board and amperage adjustment knob.",
        "category": "structural"
      },
      {
        "component_id": "comp_heatsink",
        "name": "Heatsink",
        "description": "Heat-dissipating component supporting the compressor-driver board's MOSFET and diode through thermal strips.",
        "category": "thermal"
      },
      {
        "component_id": "comp_mosfet",
        "name": "MOSFET",
        "description": "Semiconductor component on the compressor-driver board that sits on a thermal strip and is covered by a clip.",
        "category": "electrical"
      },
      {
        "component_id": "comp_diode",
        "name": "Diode",
        "description": "Semiconductor component on the compressor-driver board that sits on a thermal strip and is covered by a clip.",
        "category": "electrical"
      },
      {
        "component_id": "comp_thermal_protection_strips",
        "name": "Thermal protection strips",
        "description": "Strips applied to the heatsink beneath the MOSFET and diode.",
        "category": "thermal"
      },
      {
        "component_id": "comp_ribbon_cable",
        "name": "Ribbon cable",
        "description": "Cable connecting the control board to the power board at J7.",
        "category": "electrical"
      },
      {
        "component_id": "comp_torch_start_connector",
        "name": "TORCH START connector (J12)",
        "description": "Connector on the component side of the power board.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "Cover removed and reinstalled as part of the board replacement procedures.",
        "category": "structural"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "Barrier removed and reinstalled as part of the board replacement procedures.",
        "category": "structural"
      }
    ],
